import {
  createTable,
  createVirtualizer,
  type Table as TableController,
  type TableColumn,
  type TableOptions,
  type Virtualizer,
} from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createContext, For, merge, onCleanup, Show, untrack, useContext } from "solid-js";

import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** What `render` gets: the props of the part, `data-part` and the caller's class merged in. */
export interface TablePartProps extends PartProps, Renderable<TablePartProps, void> {}

/** A part that carries nothing of its own: the scroller, the head, the body, the caption. */
export interface TableSectionProps extends TablePartProps {}

/** How a table windows its rows: the primitive's arithmetic window inside a scrollport the kit draws. */
export interface TableWindowProps {
  /** The scrollport's height, px or a CSS length: the window needs a viewport of its own. */
  readonly height: number | string;
  /**
   * Every row's height, px. The window's arithmetic and the rendered rows have to agree, so the skin sets it on each
   * row; a row whose content is taller pushes the ones below it out of place.
   */
  readonly rowHeight: number;
  /** The rows declared either side of the viewport. @default OVERSCAN (2) */
  readonly overscan?: number | undefined;
}

export interface TableProps
  extends Omit<TableOptions, "columns" | "rows" | "id">, Renderable<TablePartProps, void> {
  readonly columns: ReadonlyArray<TableColumn>;
  readonly rows: TableOptions["rows"];
  readonly id?: string;
  /** A visible `<caption>`, which also names the table; without one pass `labels.table`. */
  readonly caption?: JSX.Element;
  readonly class?: string;
  readonly children?: JSX.Element;
  /**
   * Windows the rows: only the declared ones are rendered, in the kit's own scrollport, and `aria-rowcount` stays the
   * whole count. `renderRow` builds them; the primitive's select-all then covers the rendered window, not the whole set.
   */
  readonly virtualized?: TableWindowProps | undefined;
  /** One body row of a windowed table: the row's real id and its index in the whole set. */
  readonly renderRow?: ((row: string, index: number) => JSX.Element) | undefined;
  /** The primitive, once: a page that sorts its own data from the sort it announces. */
  readonly onReady?: (table: TableController) => void;
}

/** One body row: its id, which is what the primitive selects and what the cells of the row are asked for. */
export interface TableRowProps extends Renderable<TablePartProps, void> {
  readonly row: string;
  readonly class?: string;
  readonly children?: JSX.Element;
}

/** A header cell: its column key, and the label a sort button or the cell shows. */
export interface TableHeaderCellProps extends Renderable<TablePartProps, void> {
  readonly column: string;
  readonly class?: string;
  readonly children?: JSX.Element;
}

/** A body cell: its column key; the row comes from the `TableRow` it sits in. */
export interface TableCellProps extends Renderable<TablePartProps, void> {
  readonly column: string;
  readonly class?: string;
  readonly children?: JSX.Element;
}

/** A row's control: the row it selects. */
export interface TableRowCheckboxProps extends Renderable<TablePartProps, void> {
  readonly row: string;
  readonly class?: string;
}

const TableContext = createContext<{
  readonly table: TableController;
  readonly columns: ReadonlyArray<TableColumn>;
  /** The primitive when the table windows its rows; `undefined` when it renders every row it is given. */
  readonly virtual: Virtualizer | undefined;
  /** Every row id the host passed, in its order; a window is a slice of it. */
  readonly rows: () => ReadonlyArray<string>;
  /** A windowed table's row height, px: the row and the window's arithmetic have to agree. */
  readonly rowHeight: number | undefined;
  /** The caller's row builder, used for the declared window. */
  readonly renderRow: ((row: string, index: number) => JSX.Element) | undefined;
}>();

const RowContext = createContext<{ readonly row: string }>();

/** The row's index in the whole set, while a window declares it: it is what `aria-rowindex` announces. */
// -1 is "no window": a context default cannot be undefined, and `aria-rowindex` exists only under a window.
const RowIndexContext = createContext<number>(-1);

const scroll = css.cn(css.overflowX("auto"), css.maxWidth("100%"));

// The window's own scrollport: the table scrolls inside it, so the page does not become the list. The scrollport and the
// table take no vertical padding or margin the arithmetic cannot see (the primitive starts at the content's 0).
const viewport = css.cn(css.overflow("auto"), css.maxWidth("100%"), css.position("relative"));

// A spacer row stands in for the rows outside the window; its one cell carries the height and paints nothing.
const spacerCell = css.cn(css.padding("0"), css.border("none"), css.height("0"));

const table = css.cn(
  css.borderCollapse("collapse"),
  css.width("100%"),
  css.fontSize(t.font.size),
  css.color(t.color.text),
  css.textAlign("start"),
);

const caption = css.cn(
  css.padding(t.space._2, t.space._3),
  css.fontWeight("500"),
  css.textAlign("start"),
);

// A header cell is the group the sort arrow reads: the arrow is a child, and what it shows is the `aria-sort` the primitive
// puts on the cell, so the skin keeps no copy of the sort. A numeric column's body cells right-align, and its header's button
// follows, so the arrow stays next to the label.
const headerCell = css.cn(
  css.group("table"),
  css.padding(t.space._2, t.space._3),
  css.borderBottom("1px solid", t.color.border),
  css.fontWeight("500"),
  css.whiteSpace("nowrap"),
  css.attr("data-numeric", "true")(css.textAlign("end")),
);

const sortButton = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.gap(t.space._1),
  css.width("100%"),
  css.padding("0"),
  css.bg("transparent"),
  css.border("none"),
  css.color("inherit"),
  css.font("inherit"),
  css.textAlign("start"),
  css.cursor("pointer"),
  css.borderRadius(t.radius.sm),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
  css.within(css.attr("data-numeric", "true"), "table")(css.justifyContent("end")),
);

// The arrow is the announced sort and nothing else: hidden while the column is unsorted (so the label does not shift), up
// when ascending and the same glyph turned over when descending.
const sortArrow = css.cn(
  css.fontSize("0.6em"),
  css.color(t.color.muted),
  css.lineHeight("1"),
  css.visibility("hidden"),
  css.within(css.attr("aria-sort", "ascending"), "table")(css.visibility("visible")),
  css.within(css.attr("aria-sort", "descending"), "table")(
    css.visibility("visible"),
    css.transform("rotate(180deg)"),
  ),
);

// The selected row is the primitive's `aria-selected`; a hover on a row that selects is the affordance for the click the
// row carries, and a row that does not select stays flat.
const bodyRow = css.cn(
  css.attr("data-selectable", "true")(
    css.cursor("pointer"),
    css.hover(css.bg(t.color.buttonBackground)),
  ),
  css.attr("aria-selected", "true")(css.bg(t.color.buttonBackground)),
);

const cell = css.cn(
  css.padding(t.space._2, t.space._3),
  css.borderBottom("1px solid", t.color.border),
  css.verticalAlign("middle"),
  css.attr("data-numeric", "true")(css.textAlign("end"), css.fontVariantNumeric("tabular-nums")),
);

const selectionCell = css.cn(css.width(t.space._6), css.paddingInlineEnd("0"));

// A checkbox is drawn as a box, because a native input cannot say `mixed`: hidden until the state it follows says it is on.
const controlClass = css.cn(
  css.group(),
  css.display("inline-flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.boxSizing("border-box"),
  css.width(t.space._5),
  css.height(t.space._5),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.sm),
  css.bg(t.color.surface),
  css.color(t.color.onHighlight),
  css.cursor("pointer"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
  css.attr("aria-checked", "true")(
    css.bg(t.color.highlight),
    css.border("1px solid", t.color.highlight),
  ),
  css.attr("aria-checked", "mixed")(
    css.bg(t.color.highlight),
    css.border("1px solid", t.color.highlight),
  ),
);

const mark = css.cn(css.display("none"), css.fontSize("0.65rem"), css.lineHeight("1"));
const checkMark = css.cn(mark, css.within(css.attr("aria-checked", "true"))(css.display("inline")));
const mixedMark = css.cn(
  mark,
  css.within(css.attr("aria-checked", "mixed"))(css.display("inline")),
);

/**
 * A data table on a native `<table>`: `createTable` owns the sort, the selection and the ARIA, and this skin paints them.
 *
 * The parts are the ones the element tree needs, and each is a part a caller can `render` over: `TableScroll` (a kit-only
 * box that scrolls a wide table sideways), `Table` (the `<table>`, its caption and the primitive's context), `TableHead`
 * (the header row, with the selection cell in front as soon as the table selects; the select-all is in it only for
 * `"multiple"`), `TableHeaderCell` (a `th` whose sort
 * button carries no state but its `aria-sort`), `TableBody`, `TableRow` (a `tr`, with the row's control in front when the
 * table is selectable), `TableCell` and the two controls. A row is named by its id; a cell takes its column key.
 *
 * Sorting is the host's: the primitive announces the descriptor, `onSortChange` asks for a new one, and the host reorders
 * its own array. The arrow, the selected row and the checkbox marks are painted from the announced attributes.
 *
 * `virtualized` gives the table a window: the kit wraps the `<table>` in its own scrollport, `TableBody` renders two
 * spacer rows and the declared rows from `renderRow(row, index)`, `aria-rowcount` stays the whole count and every row
 * announces `aria-rowindex = index + 2` (the header row is 1). The primitive judges the select-all on the rows it is
 * given, and a window gives it the declared slice: **the select-all covers the rendered window**, never the rows the
 * reader cannot see. Selection itself is by real id, so a selected row that scrolls out stays selected.
 */
export const Table = (props: TableProps): JSX.Element => {
  const allRows = (): ReadonlyArray<string> =>
    typeof props.rows === "function" ? props.rows() : props.rows;
  // The window is the primitive's: one row height, no gap (a table has none), and `rows` below is the declared slice.
  const virtual =
    props.virtualized === undefined
      ? undefined
      : createVirtualizer({
          count: () => allRows().length,
          itemSize: props.virtualized.rowHeight,
          overscan: props.virtualized.overscan,
        });
  const tableControl = createTable({
    columns: props.columns,
    get rows() {
      if (virtual === undefined) {
        return props.rows;
      }
      const at = virtual.window();
      return at.last < at.first ? [] : allRows().slice(at.first, at.last + 1);
    },
    get selection() {
      return props.selection;
    },
    get sortCycle() {
      return props.sortCycle;
    },
    get sort() {
      return props.sort;
    },
    get defaultSort() {
      return props.defaultSort;
    },
    get onSortChange() {
      return props.onSortChange;
    },
    get selected() {
      return props.selected;
    },
    get defaultSelected() {
      return props.defaultSelected;
    },
    get onSelectionChange() {
      return props.onSelectionChange;
    },
    get rowCount() {
      // A window declares the whole count; every other table renders all of its rows.
      return virtual === undefined ? props.rowCount : allRows().length;
    },
    get columnCount() {
      return props.columnCount;
    },
    get labels() {
      return props.labels;
    },
    id: props.id,
  });
  untrack(() => props.onReady)?.(tableControl);

  let detach: (() => void) | undefined;
  onCleanup(() => detach?.());

  const context = {
    table: tableControl,
    columns: props.columns,
    virtual,
    rows: allRows,
    rowHeight: props.virtualized?.rowHeight,
    renderRow: props.renderRow,
  };

  const merged = merge(tableControl.tableProps, () => ({
    "data-part": "table",
    get class() {
      return css.cn(table, props.class);
    },
  }));
  const element = (): JSX.Element =>
    renderPart(props, merged, undefined, (part) => (
      <table {...part}>
        <Show when={props.caption !== undefined}>
          <TableCaption>{props.caption}</TableCaption>
        </Show>
        {props.children}
      </table>
    ));
  return (
    <TableContext value={context}>
      {props.virtualized === undefined ? (
        element()
      ) : (
        <div
          data-part="table-viewport"
          class={viewport}
          style={{
            height:
              typeof props.virtualized.height === "number"
                ? `${props.virtualized.height}px`
                : props.virtualized.height,
          }}
          ref={(node) => {
            detach = virtual?.attach(node);
          }}
        >
          {element()}
        </div>
      )}
    </TableContext>
  );
};

/** The kit-only box around a wide table: it scrolls sideways instead of pushing the page out. */
export const TableScroll = (props: TableSectionProps): JSX.Element =>
  renderPart(
    props,
    {
      "data-part": "table-scroll",
      get class() {
        return css.cn(scroll, props.class);
      },
    },
    undefined,
    (part) => <div {...part}>{props.children}</div>,
  );

/** The table's visible name: `TableOptions.labels.table` is the name of a table without one. */
export const TableCaption = (props: TableSectionProps): JSX.Element => {
  const { table: control } = useContext(TableContext);
  return renderPart(
    props,
    merge(control.captionProps, () => ({
      "data-part": "table-caption",
      get class() {
        return css.cn(caption, props.class);
      },
    })),
    undefined,
    (part) => <caption {...part}>{props.children}</caption>,
  );
};

/** The header row: a selection cell comes first whenever the rows carry a control, and the select-all only for multiple. */
export const TableHead = (props: TableSectionProps): JSX.Element => {
  const { table: control } = useContext(TableContext);
  return renderPart(
    props,
    {
      "data-part": "table-head",
      get class() {
        return css.cn(props.class);
      },
    },
    undefined,
    (part) => (
      <thead {...part}>
        <tr>
          {/* the control only for multiple selection, but the cell in every selectable mode: the body rows carry one */}
          <Show when={control.selectionMode() !== "none"}>
            <th data-part="table-select-all-cell" class={selectionCell}>
              <TableSelectAll />
            </th>
          </Show>
          {props.children}
        </tr>
      </thead>
    ),
  );
};

/** A header cell: the sort button only where the primitive says the column sorts. */
export const TableHeaderCell = (props: TableHeaderCellProps): JSX.Element => {
  const { table: control, columns } = useContext(TableContext);
  const button = control.headerButtonProps(props.column);
  const merged = merge(control.headerCellProps(props.column), () => ({
    "data-part": "table-header-cell",
    get class() {
      return css.cn(headerCell, props.class);
    },
    get "data-numeric"() {
      return columns.find((column) => column.key === props.column)?.numeric === true
        ? "true"
        : undefined;
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <th {...part}>
      {button === undefined ? (
        props.children
      ) : (
        <button {...button} data-part="table-sort" class={sortButton}>
          <span>{props.children}</span>
          <span aria-hidden="true" data-part="table-sort-arrow" class={sortArrow}>
            ▲
          </span>
        </button>
      )}
    </th>
  ));
};

/**
 * The body: every caller row as it is given it, or the declared window when the table virtualises. A window's rows come
 * from `renderRow` (the caller still builds each `TableRow`, from the row's real id), and two spacer rows stand in for the
 * rows above and below it.
 */
export const TableBody = (props: TableSectionProps): JSX.Element => {
  const { table: control, columns, virtual, rows, renderRow } = useContext(TableContext);
  const colspan = (): number => columns.length + (control.selectionMode() === "none" ? 0 : 1);
  const indexes = (): number[] => {
    if (virtual === undefined) {
      return [];
    }
    const at = virtual.window();
    return Array.from({ length: Math.max(0, at.last - at.first + 1) }, (_, step) => {
      return at.first + step;
    });
  };
  const spacer = (position: "start" | "end"): JSX.Element | undefined => {
    if (virtual === undefined) {
      return undefined;
    }
    const height = virtual.spacerProps(position).style.height;
    return (
      <tr aria-hidden="true" data-part="table-spacer" data-position={position} style={{ height }}>
        <td colspan={colspan()} data-part="table-spacer-cell" class={spacerCell} />
      </tr>
    );
  };
  return renderPart(
    props,
    {
      "data-part": "table-body",
      get class() {
        return css.cn(props.class);
      },
    },
    undefined,
    (part) => (
      <tbody {...part}>
        <Show when={virtual !== undefined} fallback={props.children}>
          {virtual === undefined ? undefined : (
            <>
              <Show when={virtual.window().above > 0}>{spacer("start")}</Show>
              <For each={indexes()}>
                {(index) => (
                  <RowIndexContext value={index}>
                    {renderRow?.(rows()[index] ?? "", index)}
                  </RowIndexContext>
                )}
              </For>
              <Show when={virtual.window().below > 0}>{spacer("end")}</Show>
            </>
          )}
        </Show>
      </tbody>
    ),
  );
};

/**
 * One body row: the primitive's `aria-selected` and click, its control in front, and the row id for every cell. In a
 * window the row also announces its place in the whole set: `aria-rowindex` counts the header row, so the first body row
 * is 2, and the total is the table's `aria-rowcount`.
 */
export const TableRow = (props: TableRowProps): JSX.Element => {
  const { table: control, rowHeight } = useContext(TableContext);
  const index = useContext(RowIndexContext);
  const merged = merge(control.rowProps(props.row), () => ({
    "data-part": "table-row",
    get class() {
      return css.cn(bodyRow, props.class);
    },
    get "data-selectable"() {
      return control.rowProps(props.row).onClick === undefined ? undefined : "true";
    },
    get "aria-rowindex"() {
      // the header row is 1, so a body row at `index` is `index + 2`
      return index < 0 ? undefined : index + 2;
    },
    get style() {
      return rowHeight === undefined ? undefined : { height: `${rowHeight}px` };
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <tr {...part}>
      <Show when={control.rowCheckboxProps(props.row)}>
        <td data-part="table-select-cell" class={selectionCell}>
          <TableRowCheckbox row={props.row} />
        </td>
      </Show>
      <RowContext value={{ row: props.row }}>{props.children}</RowContext>
    </tr>
  ));
};

/** A body cell: its `aria-colindex` while the host windows its columns, and right alignment on a numeric column. */
export const TableCell = (props: TableCellProps): JSX.Element => {
  const { table: control, columns } = useContext(TableContext);
  const row = useContext(RowContext);
  const merged = merge(control.cellProps(row?.row ?? "", props.column), () => ({
    "data-part": "table-cell",
    get class() {
      return css.cn(cell, props.class);
    },
    get "data-numeric"() {
      return columns.find((column) => column.key === props.column)?.numeric === true
        ? "true"
        : undefined;
    },
  }));
  return renderPart(props, merged, undefined, (part) => <td {...part}>{props.children}</td>);
};

/** The select-all of a multi-selectable table; nothing at all in any other mode. */
export const TableSelectAll = (props: TablePartProps): JSX.Element | null => {
  const { table: control } = useContext(TableContext);
  const all = control.selectAllProps;
  if (all === undefined) {
    return null;
  }
  return renderPart(
    props,
    merge(all, {
      "data-part": "table-select-all",
      get class() {
        return css.cn(controlClass, props.class);
      },
    }),
    undefined,
    (part) => (
      <span {...part}>
        <span aria-hidden="true" class={checkMark}>
          ✓
        </span>
        <span aria-hidden="true" class={mixedMark}>
          –
        </span>
      </span>
    ),
  );
};

/** A row's control: it stops its own click from reaching the row, which the primitive owns. */
export const TableRowCheckbox = (props: TableRowCheckboxProps): JSX.Element | null => {
  const { table: control } = useContext(TableContext);
  const own = control.rowCheckboxProps(props.row);
  if (own === undefined) {
    return null;
  }
  return renderPart(
    props,
    merge(own, {
      "data-part": "table-row-checkbox",
      get class() {
        return css.cn(controlClass, props.class);
      },
    }),
    undefined,
    (part) => (
      <span {...part}>
        <span aria-hidden="true" class={checkMark}>
          ✓
        </span>
      </span>
    ),
  );
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { createSignal, flush } from "solid-js";
import { render } from "@solidjs/web";
import { describe, expect, it } from "vite-plus/test";
import type { TableColumn, TableSelectionMode, TableSort } from "@cssints/headless";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeaderCell,
  TableRow,
  TableScroll,
} from "./table.tsx";

// Solid 2 delivers events through its delegated listener on a later turn.
const tick = () => new Promise((resolve) => setTimeout(resolve, 20));

const COLUMNS: ReadonlyArray<TableColumn> = [
  { key: "title", abbr: "Title" },
  { key: "owner", sortable: false },
  { key: "count", numeric: true },
];

/** The sort and the selection are controlled, so the test sees exactly the state the primitive announces. */
const mountTable = (
  options: { selection?: TableSelectionMode; rows?: ReadonlyArray<string> } = {},
) => {
  const root = document.createElement("div");
  document.body.append(root);
  const [rows, setRows] = createSignal<ReadonlyArray<string>>(options.rows ?? ["a", "b", "c"]);
  // `null` is "controlled and unsorted"; `undefined` would mean "uncontrolled" to the primitive
  const [sort, setSort] = createSignal<TableSort | null>(null);
  const [selected, setSelected] = createSignal<ReadonlyArray<string>>([]);
  const dispose = render(
    () => (
      <TableScroll>
        <Table
          columns={COLUMNS}
          rows={() => rows()}
          selection={options.selection ?? "multiple"}
          sort={sort()}
          onSortChange={(next) => setSort(next ?? null)}
          selected={selected()}
          onSelectionChange={setSelected}
          caption="Issues"
          labels={{ selectRow: (id) => `Choose ${id}` }}
        >
          <TableHead>
            {COLUMNS.map((column) => (
              <TableHeaderCell column={column.key}>{column.key}</TableHeaderCell>
            ))}
          </TableHead>
          <TableBody>
            {rows().map((id) => (
              <TableRow row={id}>
                {COLUMNS.map((column) => (
                  <TableCell column={column.key}>{`${id}-${column.key}`}</TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableScroll>
    ),
    root,
  );
  return {
    root,
    rows: setRows,
    selected,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

const headerCell = (root: HTMLElement, key: string): HTMLElement | null =>
  [...root.querySelectorAll<HTMLElement>("th")].find((th) =>
    th.textContent?.trim().startsWith(key),
  ) ?? null;
const arrow = (root: HTMLElement, key: string): HTMLElement | null =>
  headerCell(root, key)?.querySelector<HTMLElement>('[data-part="table-sort-arrow"]') ?? null;
const row = (root: HTMLElement, id: string): HTMLElement | null =>
  [...root.querySelectorAll<HTMLElement>("tbody td")]
    .find((cell) => cell.textContent === `${id}-title`)
    ?.closest("tr") ?? null;
const rowCheckbox = (root: HTMLElement, id: string): HTMLElement | null =>
  row(root, id)?.querySelector<HTMLElement>('[data-part="table-row-checkbox"]') ?? null;
const selectAll = (root: HTMLElement): HTMLElement | null =>
  root.querySelector<HTMLElement>('[data-part="table-select-all"]');

/** The row's real id, read off its first cell: the selection control's mark is text too. */
const rowId = (row: HTMLElement | undefined): string =>
  row?.querySelector<HTMLElement>('[data-part="table-cell"]')?.textContent?.split("-")[0] ?? "";

describe("Table skin", () => {
  it("flips aria-sort on a header click and repaints the arrow from it", async () => {
    const { root, dispose } = mountTable();
    const title = headerCell(root, "title");
    expect(title?.getAttribute("aria-sort")).toBeNull();
    expect(getComputedStyle(arrow(root, "title") as HTMLElement).visibility).toBe("hidden");

    const button = title?.querySelector<HTMLElement>('[data-part="table-sort"]');
    button?.click();
    await tick();
    expect(headerCell(root, "title")?.getAttribute("aria-sort")).toBe("ascending");
    expect(getComputedStyle(arrow(root, "title") as HTMLElement).visibility).toBe("visible");
    expect(getComputedStyle(arrow(root, "title") as HTMLElement).transform).toBe("none");

    button?.click();
    await tick();
    expect(headerCell(root, "title")?.getAttribute("aria-sort")).toBe("descending");
    // the same glyph, turned over
    expect(getComputedStyle(arrow(root, "title") as HTMLElement).transform).not.toBe("none");

    button?.click();
    await tick();
    expect(headerCell(root, "title")?.getAttribute("aria-sort")).toBeNull();
    expect(getComputedStyle(arrow(root, "title") as HTMLElement).visibility).toBe("hidden");

    // a column that does not sort has no button and no arrow at all
    const owner = [...root.querySelectorAll<HTMLElement>("th")].find(
      (th) => th.textContent?.trim() === "owner",
    );
    expect(owner?.querySelector('[data-part="table-sort"]')).toBeNull();
    expect(owner?.hasAttribute("aria-sort")).toBe(false);
    dispose();
  });

  it("toggles a row's aria-selected from its control, and paints the row from it", async () => {
    const { root, selected, dispose } = mountTable();
    expect(row(root, "a")?.getAttribute("aria-selected")).toBe("false");
    const plain = getComputedStyle(row(root, "a") as HTMLElement).backgroundColor;

    rowCheckbox(root, "a")?.click();
    await tick();
    expect(selected()).toEqual(["a"]);
    expect(row(root, "a")?.getAttribute("aria-selected")).toBe("true");
    expect(rowCheckbox(root, "a")?.getAttribute("aria-checked")).toBe("true");
    expect(getComputedStyle(row(root, "a") as HTMLElement).backgroundColor).not.toBe(plain);

    // a second click on the row itself is the primitive's own toggle, not a second gesture
    row(root, "a")?.click();
    await tick();
    expect(row(root, "a")?.getAttribute("aria-selected")).toBe("false");
    dispose();
  });

  it("keeps the select-all in step with the rows it renders, and only those", async () => {
    const { root, rows, selected, dispose } = mountTable({ rows: ["a", "b", "c"] });
    expect(selectAll(root)?.getAttribute("aria-checked")).toBe("false");

    rowCheckbox(root, "a")?.click();
    await tick();
    expect(selectAll(root)?.getAttribute("aria-checked")).toBe("mixed");

    // page 2: none of its rows is selected, though `a` still is
    rows(["d", "e"]);
    await tick();
    expect(selectAll(root)?.getAttribute("aria-checked")).toBe("false");

    // back on page 1 the mixed state is back, and the control selects the rendered window only
    rows(["a", "b", "c"]);
    await tick();
    expect(selectAll(root)?.getAttribute("aria-checked")).toBe("mixed");
    selectAll(root)?.click();
    await tick();
    expect(selectAll(root)?.getAttribute("aria-checked")).toBe("true");
    expect([...selected()].sort()).toEqual(["a", "b", "c"]);

    rows(["d", "e"]);
    await tick();
    expect(selectAll(root)?.getAttribute("aria-checked")).toBe("false");
    dispose();
  });

  it("keeps a cell in front of the row in single selection too, so the columns stay lined up", () => {
    const { root, dispose } = mountTable({ selection: "single" });
    // one control per row and no select-all: one control over one selection is meaningless
    expect(root.querySelector('[data-part="table-select-all"]')).toBeNull();
    const headerCells = root.querySelectorAll("thead th").length;
    const bodyCells = row(root, "a")?.querySelectorAll("td").length;
    expect(headerCells).toBe(COLUMNS.length + 1);
    expect(bodyCells).toBe(COLUMNS.length + 1);
    dispose();
  });

  it("right-aligns a numeric column from the layout hint, and names the select-all", () => {
    const { root, dispose } = mountTable();
    const numeric = [...root.querySelectorAll<HTMLElement>("tbody td")].find(
      (cell) => cell.textContent === "a-count",
    );
    expect(numeric?.hasAttribute("data-numeric")).toBe(true);
    expect(getComputedStyle(numeric as HTMLElement).textAlign).toBe("end");
    expect(selectAll(root)?.getAttribute("aria-label")).toBe("Select all rows");
    expect(root.querySelector("caption")?.textContent).toBe("Issues");
    dispose();
  });
});

const WINDOW_ROWS: ReadonlyArray<string> = Array.from(
  { length: 10_000 },
  (_, index) => `r${index}`,
);
const ROW_HEIGHT = 44;

/** A windowed table: 10 000 ids, a 600 px scrollport, and the caller's `renderRow` for the declared slice. */
const mountWindowedTable = () => {
  const root = document.createElement("div");
  document.body.append(root);
  const [selected, setSelected] = createSignal<ReadonlyArray<string>>([]);
  const dispose = render(
    () => (
      <Table
        columns={COLUMNS}
        rows={WINDOW_ROWS}
        selection="multiple"
        selected={selected()}
        onSelectionChange={setSelected}
        caption="Issues"
        virtualized={{ height: 600, rowHeight: ROW_HEIGHT }}
        renderRow={(id) => (
          <TableRow row={id}>
            {COLUMNS.map((column) => (
              <TableCell column={column.key}>{`${id}-${column.key}`}</TableCell>
            ))}
          </TableRow>
        )}
      >
        <TableHead>
          {COLUMNS.map((column) => (
            <TableHeaderCell column={column.key}>{column.key}</TableHeaderCell>
          ))}
        </TableHead>
        <TableBody />
      </Table>
    ),
    root,
  );
  const viewport = root.querySelector<HTMLElement>('[data-part="table-viewport"]');
  if (viewport === null) {
    throw new Error("the table did not window");
  }
  const bodyRows = (): HTMLElement[] => [
    ...root.querySelectorAll<HTMLElement>('[data-part="table-row"]'),
  ];
  return {
    root,
    viewport,
    rows: bodyRows,
    selected,
    scrollTo: (top: number): void => {
      viewport.scrollTop = top;
      viewport.dispatchEvent(new Event("scroll"));
      flush();
    },
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

describe("Table window", () => {
  it("renders only the declared window, and every row announces its place in the whole set", () => {
    const mounted = mountWindowedTable();
    const rows = mounted.rows();

    expect(mounted.root.querySelector<HTMLElement>("table")?.getAttribute("aria-rowcount")).toBe(
      "10000",
    );
    expect(rows.length).toBeGreaterThan(0);
    expect(rows.length).toBeLessThan(40);

    for (const row of rows) {
      const id = rowId(row);
      const index = Number(id.replace("r", ""));
      // the header row is 1, so body row `index` is `index + 2`
      expect(row.getAttribute("aria-rowindex")).toBe(String(index + 2));
      expect(row.getAttribute("aria-selected")).toBe("false");
    }
    // The first declared row is the first id; the window starts at the top.
    expect(rows[0]?.textContent).toContain("r0-title");
    // At the top there is no spacer above the first row.
    expect(
      mounted.root.querySelector('[data-part="table-spacer"][data-position="start"]'),
    ).toBeNull();
    expect(
      mounted.root.querySelector('[data-part="table-spacer"][data-position="end"]'),
    ).not.toBeNull();
    mounted.dispose();
  });

  it("moves the window with the scroll, re-rendering other rows with their own rowindex", () => {
    const mounted = mountWindowedTable();
    const top = mounted.rows().map((row) => row.getAttribute("aria-rowindex"));

    mounted.scrollTo(60 * ROW_HEIGHT);
    const rows = mounted.rows();

    expect(rows.map((row) => row.getAttribute("aria-rowindex"))).not.toEqual(top);
    expect(rows.length).toBeLessThan(40);
    for (const row of rows) {
      const id = rowId(row);
      expect(row.getAttribute("aria-rowindex")).toBe(String(Number(id.replace("r", "")) + 2));
    }
    const start = mounted.root.querySelector<HTMLElement>(
      '[data-part="table-spacer"][data-position="start"]',
    );
    expect(start).not.toBeNull();
    expect(start?.getAttribute("aria-hidden")).toBe("true");
    mounted.dispose();
  });

  it("keeps the select-all honest: it covers the rendered window, and a row toggles by its real id", async () => {
    const mounted = mountWindowedTable();
    const rows = mounted.rows();
    const first = rowId(rows[0]);

    // One control over the whole set would mean selecting 10 000 rows the reader cannot see.
    selectAll(mounted.root)?.click();
    await tick();
    expect(mounted.selected().length).toBe(rows.length);
    expect(mounted.selected().length).toBeLessThan(40);
    expect(mounted.selected()).toContain(first);
    expect(mounted.selected()).not.toContain("r9999");

    // A row's control toggles the row's id, not its position in the window.
    const second = rowId(rows[1]);
    rowCheckbox(mounted.root, second)?.click();
    await tick();
    expect(mounted.selected()).not.toContain(second);
    expect(mounted.selected()).toContain(first);

    // A hand scroll leaves the window's selection behind and the new window's select-all covers the new rows.
    mounted.scrollTo(80 * ROW_HEIGHT);
    await tick();
    const far = rowId(mounted.rows()[0]);
    expect([...mounted.selected()].sort()).not.toContain(far);
    selectAll(mounted.root)?.click();
    await tick();
    expect(mounted.selected()).toContain(far);
    // the rows selected before the window moved are still selected
    expect(mounted.selected()).toContain(first);
    mounted.dispose();
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
